sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
uniform float blur;
uniform float alpha;
uniform float fill;
uniform float fade;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float b = float(blurred.eval(coord).a);
    float t = clamp(1.0 - b * 2.0, 0.0, 1.0);
    t *= t;
    float cover = smoothstep(0.0, 0.06, b) * clamp(alpha, 0.0, 1.0);
    if (fade > 0.5) cover *= 1.0 - t;
    float3 rgb = mix(float3(color1.rgb), float3(color2.rgb), t);
    float ca = cover * mix(float(color1.a), float(color2.a), t);
    half4 halo = half4(half3(rgb) * half(ca), half(ca));
    half4 body = src * half(clamp(fill, 0.0, 1.0));
    return body + halo * (1.0 - body.a);
}
